# 64_hansard_self_regarding_pilot.R
# STATUS: PILOT / EXPLORATORY — not core pipeline
#
# Research question: are MP speeches becoming more self-regarding over time?
# Operationalisation: ratio of career/position references to
# constituency/policy references in individual speeches.
# Avoids pronoun-based measures (confounded by informalisation of register).
#
# DATA: ParlSpeech V2 (Rauh & Schwalbach 2020, Harvard Dataverse)
#   UK House of Commons speeches, 1988–2019
#   DOI: https://dataverse.harvard.edu/dataset.xhtml?persistentId=doi:10.7910/DVN/L4OAKN
#   File to download: Corp_HouseOfCommons_V2.rds (~1.5GB)
#   Save to: data/raw/Corp_HouseOfCommons_V2.rds
#
# PILOT SCOPE: Three parliaments (within ParlSpeech coverage)
#   Pre-2014:  1997–2001 (Blair 1st term)
#              2005–2010 (Blair 3rd / Brown)
#   Post-2014: 2015–2019 (Cameron/May/Johnson)
#
# KNOWN LIMITATIONS:
#   - Dictionary not validated against hand-coded gold standard
#   - Frontbench/ministerial role naturally produces more career/position
#     references — controlling for this is essential before drawing conclusions
#   - ParlSpeech ends ~Dec 2019; 2019–2024 parliament not covered
#   - Treat output as exploratory; verify top/bottom hits manually
#
# OUTPUT: figures/ch3_hansard_self_regarding_pilot.png
#         console diagnostics for spot-checking

pacman::p_load(tidyverse, tidytext, patchwork)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})  # portable project root: works via Rscript from anywhere, or falls back to
    # getwd() when sourced interactively (assumes ch3_pipeline_restored/ as cwd)
PROJECT <- .ROOT
OUT_DIR  <- file.path(PROJECT, "figures")
DATA_RAW <- file.path(PROJECT, "data/raw")

NAVY <- "#1F3864"
RED  <- "#d7191c"
GREY <- "#888888"

# ===========================================================================
# 1. Load ParlSpeech data
# ===========================================================================

parlspeech_path <- file.path(PROJECT, "data/dataverse_files/Corp_HouseOfCommons_V2.rds")

if (!file.exists(parlspeech_path)) {
  stop(
    "ParlSpeech data not found.\n",
    "Download Corp_HouseOfCommons_V2.rds from:\n",
    "  https://dataverse.harvard.edu/dataset.xhtml?persistentId=doi:10.7910/DVN/L4OAKN\n",
    "Save to: ", parlspeech_path
  )
}

cat("Loading ParlSpeech data (this may take a moment)...\n")
parl_raw <- readRDS(parlspeech_path)
cat("Loaded:", nrow(parl_raw), "speeches\n")
cat("Columns:", paste(names(parl_raw), collapse = ", "), "\n")
cat("Date range:", format(min(parl_raw$date)), "to", format(max(parl_raw$date)), "\n")

# ===========================================================================
# 2. Assign all available speeches to parliaments (1988–2019)
# ===========================================================================
# ParlSpeech covers Nov 1988 – Dec 2019: 8 full parliaments available.
# Using all data (not a pilot selection) for a proper long-run picture.
# Parliament dates: dissolution to dissolution.

parl_filtered <- parl_raw |>
  mutate(date = as.Date(date)) |>
  filter(date >= as.Date("1988-11-22")) |>   # start of ParlSpeech coverage
  mutate(
    parliament = case_when(
      date <= as.Date("1992-04-09") ~ "1988-1992",  # Thatcher/Major
      date <= as.Date("1997-05-01") ~ "1992-1997",  # Major
      date <= as.Date("2001-06-07") ~ "1997-2001",  # Blair 1st
      date <= as.Date("2005-05-05") ~ "2001-2005",  # Blair 2nd
      date <= as.Date("2010-05-06") ~ "2005-2010",  # Blair 3rd/Brown
      date <= as.Date("2015-05-07") ~ "2010-2015",  # Cameron coalition
      date <= as.Date("2017-06-08") ~ "2015-2017",  # Cameron/May
      TRUE                          ~ "2017-2019"   # May/Johnson
    ),
    era = if_else(date < as.Date("2014-05-01"), "Pre-2014", "Post-2014")
  )

cat("\nSpeeches by parliament (before sampling):\n")
print(count(parl_filtered, parliament, era))

# Sample up to 5,000 speeches per parliament for speed
set.seed(42)
parl_sample <- parl_filtered |>
  filter(nchar(text) > 300) |>   # drop very short contributions
  group_by(parliament) |>
  group_modify(~ slice_sample(.x, n = min(5000, nrow(.x)))) |>
  ungroup()

cat("\nSample sizes after filtering and sampling:\n")
print(count(parl_sample, parliament))

# ===========================================================================
# 3. Define dictionaries
# ===========================================================================
# Career/position: references to speaker's own role, department, appointment.
# These are less susceptible to register informalisation than pronouns.
# Still imperfect: ministerial speech will naturally score higher.
# The test is whether the ratio rises *over time*, not in absolute terms.

career_terms <- c(
  "my role", "my position", "my appointment", "my department",
  "my portfolio", "my responsibilities", "my tenure", "my office",
  "my capacity", "my ministerial", "my shadow", "my career",
  "as minister", "as secretary of state", "as chancellor",
  "as home secretary", "as foreign secretary", "as prime minister",
  "in my view", "i believe", "i think", "i feel"
  # Note: last four are borderline — remove if ratio looks inflated
)

# Constituency/policy: references outward to people or evidence
policy_terms <- c(
  "my constituents", "my constituency", "people in my",
  "the evidence", "the research shows", "the data",
  "the public", "communities", "families",
  "workers", "businesses", "this policy", "the policy",
  "the bill", "the legislation", "the government must",
  "we must", "we should", "we need to"
)

cat("\nCareer dictionary:", length(career_terms), "terms\n")
cat("Policy dictionary:", length(policy_terms), "terms\n")

# ===========================================================================
# 4. Score speeches
# ===========================================================================

cat("\nScoring speeches (may take several minutes)...\n")

score_speech <- function(text, terms) {
  text_lower <- tolower(text)
  sum(str_count(text_lower, fixed(terms)))
}

parl_scored <- parl_sample |>
  mutate(
    n_words   = str_count(text, "\\S+"),
    n_career  = map_int(text, score_speech, career_terms),
    n_policy  = map_int(text, score_speech, policy_terms),
    # Rates per 1,000 words
    rate_career = (n_career / n_words) * 1000,
    rate_policy = (n_policy / n_words) * 1000,
    # Self-regarding ratio: career as share of career + policy
    # Laplace smoothing to handle zero-match speeches
    self_ratio  = (n_career + 0.5) / (n_career + n_policy + 1)
  ) |>
  filter(n_words >= 50)  # drop interventions too short to score

cat("Scored speeches:", nrow(parl_scored), "\n")

# Summary by parliament
cat("\nMean scores by parliament:\n")
parl_scored |>
  group_by(parliament, era) |>
  summarise(
    n            = n(),
    mean_career  = mean(rate_career),
    mean_policy  = mean(rate_policy),
    mean_ratio   = mean(self_ratio),
    .groups = "drop"
  ) |>
  print()

# ===========================================================================
# 5. Diagnostics — spot-check top and bottom speeches
# ===========================================================================

cat("\n=== Highest self-ratio speeches (manual check for false positives) ===\n")
parl_scored |>
  arrange(desc(self_ratio)) |>
  select(date, speaker, parliament, self_ratio, n_career, n_policy, n_words) |>
  head(10) |>
  print()

cat("\n=== Lowest self-ratio speeches ===\n")
parl_scored |>
  arrange(self_ratio) |>
  select(date, speaker, parliament, self_ratio, n_career, n_policy, n_words) |>
  head(10) |>
  print()

# ===========================================================================
# 6. Figure
# ===========================================================================

parl_levels <- c("1988-1992", "1992-1997", "1997-2001", "2001-2005",
                  "2005-2010", "2010-2015", "2015-2017", "2017-2019")

parl_labels <- c(
  "1988-1992" = "1988–92\nThatcher/Major",
  "1992-1997" = "1992–97\nMajor",
  "1997-2001" = "1997–01\nBlair 1",
  "2001-2005" = "2001–05\nBlair 2",
  "2005-2010" = "2005–10\nBlair 3/Brown",
  "2010-2015" = "2010–15\nCameron",
  "2015-2017" = "2015–17\nCameron/May",
  "2017-2019" = "2017–19\nMay/Johnson"
)

parl_agg <- parl_scored |>
  group_by(parliament, era) |>
  summarise(
    mean_ratio = mean(self_ratio),
    se_ratio   = sd(self_ratio) / sqrt(n()),
    n          = n(),
    .groups    = "drop"
  ) |>
  mutate(
    lo = mean_ratio - 1.96 * se_ratio,
    hi = mean_ratio + 1.96 * se_ratio,
    parliament = factor(parliament, levels = parl_levels)
  )

p <- ggplot(parl_agg, aes(x = parliament, y = mean_ratio, group = 1)) +
  geom_hline(yintercept = mean(parl_agg$mean_ratio),
             linetype = "dashed", colour = GREY, linewidth = 0.4) +
  geom_line(colour = "grey70", linewidth = 0.6) +
  geom_errorbar(aes(ymin = lo, ymax = hi),
                width = 0.12, linewidth = 0.7, colour = NAVY) +
  geom_point(size = 4, colour = NAVY) +
  scale_x_discrete(labels = parl_labels) +
  scale_y_continuous(labels = scales::percent_format(accuracy = 0.1)) +
  labs(
    title    = "Self-regarding speech ratio in parliamentary debate, 1988\u20132019",
    subtitle = paste0(
      "Self-regarding ratio = career/position references as share of (career + constituency/policy) references.\n",
      "Higher = more self-regarding. Eight parliaments, up to 5,000 sampled speeches each."
    ),
    x       = "Parliament",
    y       = "Self-regarding ratio (mean, 95% CI)",
    caption = paste0(
      "Source: ParlSpeech V2 (Rauh & Schwalbach 2020), Harvard Dataverse doi:10.7910/DVN/L4OAKN.\n",
      "Dictionary: ", length(career_terms), " career/position terms vs ",
      length(policy_terms), " constituency/policy terms. Laplace-smoothed ratio.\n",
      "Exploratory — dictionary not yet validated against gold standard. ",
      "Key confound: frontbench role produces more career/position references. ",
      "Interpret trend, not levels."
    )
  ) +
  theme_minimal(base_size = 11) +
  theme(
    plot.title       = element_text(face = "bold", size = 12, colour = NAVY),
    plot.subtitle    = element_text(size = 9, colour = GREY, lineheight = 1.3),
    plot.caption     = element_text(size = 7, colour = GREY),
    legend.position  = "top",
    panel.grid.minor = element_blank(),
    axis.line        = element_line(colour = "grey80", linewidth = 0.3)
  )

out_path <- file.path(OUT_DIR, "ch3_hansard_self_regarding_pilot.png")
ggsave(out_path, p, width = 9, height = 5.5, dpi = 300)
cat("\nFigure saved:", out_path, "\n")

